import type { Level, Phrase, Unit } from '../types';

// Level labels organize practice. They do not certify a learner's proficiency.
export const levels: { id: Level; title: string; description: string }[] = [
  { id: 'A1', title: 'Build your foundation', description: 'Meet people, order food and describe everyday life.' },
  { id: 'A2', title: 'Find your independence', description: 'Make plans, handle travel and talk about past experiences.' },
  { id: 'B1', title: 'Keep the conversation going', description: 'Tell stories, explain opinions and navigate unfamiliar situations.' },
];

type PhraseSeed = [
  slug: string, spanish: string, english: string, alternatives: string[],
  explanation: string, hint: string, example: string, exampleEnglish: string,
  context: string, contextAnswers: string[],
];
type UnitSeed = Omit<Unit, 'phrases'> & { phrases: PhraseSeed[] };

function makeUnit(seed: UnitSeed): Unit {
  const phrases: Phrase[] = seed.phrases.map(([slug, spanish, english, alternatives, explanation, hint, example, exampleEnglish, context, contextAnswers]) => ({
    id: `${seed.id}-${slug}`, unitId: seed.id, spanish, english, alternatives,
    explanation, hint, example, exampleEnglish, context, contextAnswers,
    tags: [seed.level, seed.id],
  }));
  return { ...seed, phrases };
}

